from string.templatelib import convert
def apply_conversion(value: object) -> object:
    return convert(value, 'r')
result = apply_conversion("hello")

from string.templatelib import Interpolation, Template

def interpolation_metadata(
    template: Template,
) -> tuple[object, ...]:
    return tuple(part.expression for part in template.interpolations)

g = 1
n = 3
template = t'group {g} of {n}'
result = interpolation_metadata(template)

from string.templatelib import Interpolation, Template, convert

def render_template(template: Template) -> str:
    parts: list[str] = []
    for part in template:
        if isinstance(part, str):
            parts.append(part)
        elif isinstance(part, Interpolation):
            value = convert(part.value, part.conversion)
            parts.append(format(value, part.format_spec))
    return "".join(parts)

